def equal(a, b):
    if a is None or b is None:
        return a is None and b is None
    if type(a) == bool or type(b) == bool:
        return type(a) == bool and type(b) == bool and a == b
    if type(a) == int or type(a) == float:
        return (type(b) == int or type(b) == float) and a == b
    if type(a) == str or type(b) == str:
        return type(a) == str and type(b) == str and a == b
    if type(a) == list or type(b) == list:
        if type(a) != list or type(b) != list or len(a) != len(b):
            return False
        i = 0
        while i < len(a):
            if not equal(a[i], b[i]):
                return False
            i += 1
        return True
    if type(a) == dict or type(b) == dict:
        if type(a) != dict or type(b) != dict or len(a) != len(b):
            return False
        for key in a:
            if key not in b or not equal(a[key], b[key]):
                return False
        return True
    return False

